async loadPreset(preset: Preset, targetRegion: number): Promise<any> {
		const body = {
			auxiliary: {
				keyFrame: { enable: 1 },
				switchEffect: { type: 1, time: 500 },
				swapEnable: 1,
				effect: { enable: 1 },
			},
			serial: preset.serial,
			targetRegion,
			presetId: preset.guid,
		}

		return this.http!.post(this.cfg.endpoints.preset.apply, body)
	}

